import{_ as o,o as r,c as e,ag as n}from"./chunks/framework.D5hoimZQ.js";const p=JSON.parse('{"title":"🔬 科学快报 | 2026年7月14日（第 ? 期 · 事后重建版）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"science-log/src/reconstructed/2026-07-14.md","filePath":"science-log/src/reconstructed/2026-07-14.md"}'),a={name:"science-log/src/reconstructed/2026-07-14.md"};function s(g,t,i,u,l,c){return r(),e("div",null,[...t[0]||(t[0]=[n('<h1 id="🔬-科学快报-2026年7月14日-第-期-·-事后重建版" tabindex="-1">🔬 科学快报 | 2026年7月14日（第 ? 期 · 事后重建版） <a class="header-anchor" href="#🔬-科学快报-2026年7月14日-第-期-·-事后重建版" aria-label="Permalink to &quot;🔬 科学快报 | 2026年7月14日（第 ? 期 · 事后重建版）&quot;">​</a></h1><blockquote><p>⚠️ <strong>事后重建版</strong>：本文件<strong>不是</strong>当日发布原文。由 2026-11-05 依 arXiv / CrossRef <strong>按发布日期回溯检索</strong>生成，选题与排序均为事后判定，<strong>不代表历史原貌</strong>。 说明：2026-07-14 为<strong>周二</strong>。CrossRef 当日命中：Nature（0028-0836）16 条，其中研究论文 <code>10.1038/s41586-…</code> <strong>0 条</strong>（当日仅 <code>d41586</code> 新闻稿；Nature 研究论文集中在前一日 07-13 与次日 07-15）；PNAS（0027-8424）21 条；Science 系（10.1126）8 条（1 条撤稿、2 篇 <em>Science Signaling</em> 研究论文、其余为新闻）。故科学 5 篇全部取自<strong>当日真实命中</strong>（PNAS 4 + Science Signaling 1）。 取证：CrossRef（Nature 0028-0836 / Science 10.1126 / PNAS 0027-8424）+ arXiv 日期区间 ｜ 重建日：2026-11-05</p></blockquote><h2 id="🔬-科学前沿" tabindex="-1">🔬 科学前沿 <a class="header-anchor" href="#🔬-科学前沿" aria-label="Permalink to &quot;🔬 科学前沿&quot;">​</a></h2><h3 id="🧬-多巴胺神经元偏爱-囤积-线粒体dna重排" tabindex="-1">🧬 多巴胺神经元偏爱&quot;囤积&quot;线粒体DNA重排 <a class="header-anchor" href="#🧬-多巴胺神经元偏爱-囤积-线粒体dna重排" aria-label="Permalink to &quot;🧬 多巴胺神经元偏爱&quot;囤积&quot;线粒体DNA重排&quot;">​</a></h3><p><strong>Dopaminergic neurons preferentially accumulate mtDNA rearrangements</strong><em>PNAS（2026）</em></p><p>黑质多巴胺神经元的线粒体DNA（mtDNA）缺失水平远高于其他脑区，是帕金森病最古老的病理线索之一，但&quot;为什么偏偏是这里&quot;一直没有答案。迈阿密大学米勒医学院 Carlos T. Moraes 团队用<strong>线粒体靶向限制性内切酶 mitoPstI</strong> 在小鼠体内瞬时制造 mtDNA 双链断裂，发现重排并不随机——断点既落在 PstI 切割位点，也反复出现在 <strong>MTERF1 结合位点</strong>与 <strong>D-loop 边缘</strong>，提示 mtDNA 存在&quot;重组热点&quot;。更关键的是：同样处理下，<strong>多巴胺能神经元</strong>在酶表达停止后仍持续累积重排，<strong>谷氨酸能神经元</strong>则没有；若敲除 mtDNA 复制体（replisome）组分，这种累积被削弱。结论是——多巴胺神经元的高突变负荷不是&quot;损伤更多&quot;，而是<strong>依赖复制的重排固定</strong>更活跃，这为帕金森病的线粒体假说补上了机制一环。</p><p>📎 DOI: <a href="https://doi.org/10.1073/pnas.2601897123" target="_blank" rel="noreferrer">10.1073/pnas.2601897123</a></p><h3 id="💉-用-pmo-嵌合体-定点降解-α-突触核蛋白-mrna" tabindex="-1">💉 用 PMO 嵌合体&quot;定点降解&quot;α-突触核蛋白 mRNA <a class="header-anchor" href="#💉-用-pmo-嵌合体-定点降解-α-突触核蛋白-mrna" aria-label="Permalink to &quot;💉 用 PMO 嵌合体&quot;定点降解&quot;α-突触核蛋白 mRNA&quot;">​</a></h3><p><strong>Targeted α-synuclein mRNA degradation by PMO-based RNA-degrading chimeras</strong><em>PNAS（2026）</em></p><p>α-突触核蛋白（αSyn）本质无序、构象异质，直接靶向蛋白极难；于是约翰霍普金斯大学医学院（Ted Dawson 团队所在神经再生与干细胞项目）Ning Wang 等把矛头转向 <strong>SNCA 转录本</strong>。他们做出<strong>磷酰二胺吗啉寡聚物（PMO）为基础的 RNA 降解嵌合体（RDC）</strong>：一端结合 <em>SNCA</em> mRNA 的 <strong>5′ UTR</strong>，另一端<strong>招募 RNase L</strong> 就地切割。筛了 9 条后优化出 <strong>4-D1</strong>，在 HEK293T 中人源化 <em>SNCA</em> 小鼠原代皮层神经元、以及人 iPSC 来源皮层神经元中均降低 SNCA mRNA 与 αSyn 蛋白；并且<strong>阻断了患者来源 αSyn 纤维诱导的&quot;类朊病毒播种&quot;</strong>、保护神经元免于纤维毒性。体内人源化小鼠也证实其降低 SNCA mRNA。这是&quot;降底物而非清聚集体&quot;的路线，对突触核蛋白病是一次给药逻辑的切换。</p><p>📎 DOI: <a href="https://doi.org/10.1073/pnas.2526461123" target="_blank" rel="noreferrer">10.1073/pnas.2526461123</a></p><h3 id="🛡️-hiv-mper-广谱中和抗体-两条脂膜识别路线-和一个-多反应性开关" tabindex="-1">🛡️ HIV MPER 广谱中和抗体：两条脂膜识别路线，和一个&quot;多反应性开关&quot; <a class="header-anchor" href="#🛡️-hiv-mper-广谱中和抗体-两条脂膜识别路线-和一个-多反应性开关" aria-label="Permalink to &quot;🛡️ HIV MPER 广谱中和抗体：两条脂膜识别路线，和一个&quot;多反应性开关&quot;&quot;">​</a></h3><p><strong>Structural basis of membrane engagement and polyreactivity control in HIV-1 MPER broadly neutralizing antibodies</strong><em>PNAS（2026）</em></p><p>MPER（膜近端外部区）高度保守，是 HIV 广谱中和抗体的黄金靶点，但它的表位是&quot;肽 + 病毒膜脂&quot;的复合体——想中和就得碰脂，碰脂又容易变成&quot;什么膜都黏&quot;的多反应性抗体（自体反应风险）。Scripps Research 的 Ian A. Wilson、Andrew B. Ward、William R. Schief 团队解出 <strong>DH511.1（记忆B细胞来源）、DH511.12P（浆细胞来源）、VRC42.01</strong> 与 MPER 肽 + 磷脂酸的晶体结构，以及 <strong>DH511.2 结合膜 embedded Env 的冷冻电镜重构</strong>。整合分析显示两种策略：<strong>沟槽介导型</strong>（10E8、DH511）用抗体-膜界面的沟槽以特定角度切入膜；<strong>重链介导型</strong>（4E10、PGZL1、VRC42）靠带正电的 <strong>CDR H1</strong> 直接抓脂头基。多反应性的差别藏在电荷细节里：DH511 谱系成员的心磷脂反应性随成熟阶段变化，PGZL1 更是额外长出一个 <strong>CDR H3 负电斑块</strong>，与负电脂头基静电相斥，从而压住非特异结合。这给了免疫原设计一把&quot;既要贴膜、又要挑剔&quot;的尺子。</p><p>📎 DOI: <a href="https://doi.org/10.1073/pnas.2609827123" target="_blank" rel="noreferrer">10.1073/pnas.2609827123</a></p><h3 id="🧱-冷冻休眠-硅化-给哺乳动物细胞套上-传两三代就消失-的硅壳" tabindex="-1">🧱 冷冻休眠 + 硅化：给哺乳动物细胞套上&quot;传两三代就消失&quot;的硅壳 <a class="header-anchor" href="#🧱-冷冻休眠-硅化-给哺乳动物细胞套上-传两三代就消失-的硅壳" aria-label="Permalink to &quot;🧱 冷冻休眠 + 硅化：给哺乳动物细胞套上&quot;传两三代就消失&quot;的硅壳&quot;">​</a></h3><p><strong>Cryogenic silicification enables nongenetic functional continuity across mammalian cell generations</strong><em>PNAS（2026）</em></p><p>哺乳动物细胞天生柔软（杨氏模量约 <strong>0.1–10 kPa</strong>，取决于 F-actin 骨架组织），机械与环境胁迫下极易碎，这限制了它们在非生理条件下的操作与部署。广东省低碳合成生物工程中心 / 华南理工大学 W. Zhu 与 C. Jeffrey Brinker 等提出<strong>冷冻休眠赋能的硅化（cryosilicification）</strong>：在低温休眠造成的<strong>瞬时可透膜</strong>窗口里让硅酸涌入胞内，随后经<strong>蛋白介导的缩合</strong>形成跨越胞内外、贴合细胞的<strong>无定形二氧化硅网络</strong>，得到&quot;<strong>Silicacytes</strong>&quot;。这些硅-细胞杂合体机械强度大幅提升、抗多种环境胁迫，且<strong>不改变遗传身份</strong>；硅结构在分裂时被逐步分配，形成&quot;<strong>伪遗传</strong>&quot;增强——能撑 <strong>2–3 代</strong>后逐渐消失。可逆、有时限的加固，等于给细胞工程开了一个&quot;非基因的跨代功能延续&quot;通道。</p><p>📎 DOI: <a href="https://doi.org/10.1073/pnas.2604560123" target="_blank" rel="noreferrer">10.1073/pnas.2604560123</a></p><h3 id="⚗️-甘油-3-磷酸不只是脂肪原料-还是-mtorc1-的-脂质信号" tabindex="-1">⚗️ 甘油-3-磷酸不只是脂肪原料，还是 mTORC1 的&quot;脂质信号&quot; <a class="header-anchor" href="#⚗️-甘油-3-磷酸不只是脂肪原料-还是-mtorc1-的-脂质信号" aria-label="Permalink to &quot;⚗️ 甘油-3-磷酸不只是脂肪原料，还是 mTORC1 的&quot;脂质信号&quot;&quot;">​</a></h3><p><strong>Glycerol 3-phosphate activates lipid metabolism through GATOR2-dependent regulation of mTORC1</strong><em>Science Signaling（2026）</em></p><p>mTORC1 长期被当作&quot;氨基酸/生长因子传感器&quot;，但肝脏里决定它要不要开动脂肪合成的，可能是一个<strong>脂质中间体</strong>。亚利桑那大学医学院（Phoenix）Hyoungjoo Kwon、Shogo Yamada 等发现，<strong>甘油-3-磷酸（G3P）<strong>本身就是激活 mTORC1 的刺激信号。原代小鼠肝细胞中 G3P 主要来自</strong>甘油激酶（GK）</strong>；肝特异性敲除 GK 的小鼠，不仅肝甘油三酯生成与储存下降，**mTORC1 依赖的 de novo lipogenesis（DNL）**也同步下调。逐级阻断 G3P 下游代谢、并用甘油磷酸脱氢酶缺陷细胞/小鼠排除旁路后，mTORC1 活性与 <strong>G3P 绝对量</strong>正相关，且不由前体或其他甘油代谢物介导；野生型 GK 经 <strong>GATOR2</strong>（同时也是氨基酸激活 mTORC1 的枢纽）传递信号，而 GK 缺陷症中的失活突变体则失效。肥胖状态下甘油升高 → GK 产 G3P 增多 → mTORC1 开大 → 肝脏 TG 堆积，这条链把 MAFLD 的&quot;原料供给&quot;与&quot;信号指令&quot;接成了一根线。</p><p>📎 DOI: <a href="https://doi.org/10.1126/scisignal.aeb7989" target="_blank" rel="noreferrer">10.1126/scisignal.aeb7989</a></p><h2 id="🤖-ai-前沿" tabindex="-1">🤖 AI 前沿 <a class="header-anchor" href="#🤖-ai-前沿" aria-label="Permalink to &quot;🤖 AI 前沿&quot;">​</a></h2><h3 id="🧰-memoharness-让-agent-harness-从自己的执行记录里学习" tabindex="-1">🧰 MemoHarness：让 agent harness 从自己的执行记录里学习 <a class="header-anchor" href="#🧰-memoharness-让-agent-harness-从自己的执行记录里学习" aria-label="Permalink to &quot;🧰 MemoHarness：让 agent harness 从自己的执行记录里学习&quot;">​</a></h3><p><strong>MemoHarness: Agent Harnesses That Learn from Experience</strong><em>arXiv（2026）</em></p><p>agent 的能力不只来自基座模型，还来自 <strong>harness</strong>——构造 prompt、管状态、调工具、编排执行的那层外部控制代码。但现有自动优化多盯着 prompt / pipeline / workflow 这类&quot;窄产物&quot;，线上部署又往往所有 case 共用一套全局 harness。Yue Huang、Wenjie Wang 等提出 <strong>MemoHarness</strong>：把 harness 拆成<strong>六个可编辑控制维度</strong>，用<strong>双层经验库</strong>分别存&quot;单例诊断&quot;与&quot;蒸馏出的全局模式&quot;，推理时<strong>检索经验</strong>即可为每个测试样例自适应装配 harness——<strong>不需要测试时标签、反馈或额外搜索</strong>。在 shell-agent、代码生成、分析推理三类基准上均优于固定 harness，并对未见过的套件与基座模型表现出<strong>选择性迁移</strong>；由于检索到的经验大部分可缓存，额外上下文成本仍可控。作者也明确把统计稳健性与组件归因留作后续工作。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2607.14159" target="_blank" rel="noreferrer">2607.14159</a></p><h3 id="🗺️-harness-handbook-把-行为-映射回代码-破解-harness-演化瓶颈" tabindex="-1">🗺️ Harness Handbook：把&quot;行为&quot;映射回代码，破解 harness 演化瓶颈 <a class="header-anchor" href="#🗺️-harness-handbook-把-行为-映射回代码-破解-harness-演化瓶颈" aria-label="Permalink to &quot;🗺️ Harness Handbook：把&quot;行为&quot;映射回代码，破解 harness 演化瓶颈&quot;">​</a></h3><p><strong>Harness Handbook: Making Evolving Agent Harnesses Readable, Navigable, and Editable</strong><em>arXiv（2026）</em></p><p>生产级 harness 又大又紧耦合、行为在代码里&quot;分布式&quot;存在；而修改请求说的是&quot;系统应该做什么&quot;，仓库却是按文件模块组织的——于是<strong>行为定位（behavior localization）<strong>成了 harness 演化的中心瓶颈，代码检索、仓库索引、长上下文都只能缓解、不能替代这一步。Ruhan Wang、Yucheng Shi 等提出 <strong>Harness Handbook</strong>：用</strong>静态分析 + LLM 辅助结构化</strong>自动合成一份&quot;以行为为中心&quot;的表示，把每个行为链接到对应源码；再配 <strong>Behavior-Guided Progressive Disclosure（BGPD）</strong>，引导 agent 从高层行为逐级下钻到实现细节，并把候选位置对<strong>当前源码</strong>做校验。在两个开源 harness 的多样修改请求上，Handbook 辅助的规划<strong>提升了行为定位与编辑计划质量，同时消耗更少的 planner token</strong>，收益最大的是<strong>分散位点、少走路径、跨模块交互</strong>。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2607.13285" target="_blank" rel="noreferrer">2607.13285</a></p><h3 id="🧠-kv-cache-的-结构角色偏见-把注意力质量当信号能量-会精准留下噪声" tabindex="-1">🧠 KV cache 的&quot;结构角色偏见&quot;：把注意力质量当信号能量，会精准留下噪声 <a class="header-anchor" href="#🧠-kv-cache-的-结构角色偏见-把注意力质量当信号能量-会精准留下噪声" aria-label="Permalink to &quot;🧠 KV cache 的&quot;结构角色偏见&quot;：把注意力质量当信号能量，会精准留下噪声&quot;">​</a></h3><p><strong>Adaptive Filtering of the KV Cache: Diagnosing and Correcting Structural-Role Bias in LLM Inference</strong><em>arXiv（2026）</em></p><p>以 H2O 为代表的<strong>基于注意力的 KV cache 淘汰</strong>，把 token 的累积注意力质量当作&quot;信号能量&quot;，保留最重的那些。Soumil Mandal 指出：在<strong>schema 密集</strong>的输入流（如嵌套 JSON）上，这个打分变成一个<strong>非平稳滤波器</strong>，会不成比例地留下噪声——<strong>非内容&quot;汇&quot;角色</strong>（分隔符、空白）携带的能量比任何内容角色高一个数量级，<strong>结构 KEY token 的保留率约为承载答案的 VALUE token 的 1.8 倍</strong>。后果是：预算 5% 时，保留状态的 SNR 恶化，<strong>exact-match 准确率从 88% 直接塌到 0%</strong>。这不是&quot;压缩太狠&quot;，而是<strong>打分函数与输入的统计结构错配</strong>——注意力质量并不等于信息量。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2607.13205" target="_blank" rel="noreferrer">2607.13205</a></p><h3 id="⚡-电网仿真-×-多智能体-×-mcp-把-pypowsybl-交给-ai-调度" tabindex="-1">⚡ 电网仿真 × 多智能体 × MCP：把 pypowsybl 交给 AI 调度 <a class="header-anchor" href="#⚡-电网仿真-×-多智能体-×-mcp-把-pypowsybl-交给-ai-调度" aria-label="Permalink to &quot;⚡ 电网仿真 × 多智能体 × MCP：把 pypowsybl 交给 AI 调度&quot;">​</a></h3><p><strong>Orchestrating Power Grid Studies with Multi-Agent AI and MCP Servers</strong><em>arXiv（2026）</em></p><p>这是一篇立场论文（position paper）：在<strong>输电系统运营商（TSO）<strong>语境下，如何用 agentic AI 与 <strong>Model Context Protocol（MCP）</strong> 支撑电网研究。作者 Jérôme Picault、Clément Goubet 先梳理&quot;agent 辅助电网研究&quot;的工业级需求，再给出 <strong>pypowsybl-mcp</strong>——一个把开源仿真库 <strong>pypowsybl</strong> 的选定能力暴露给 AI agent 的 MCP 接口：agent 通过标准化工具调用</strong>建算例、跑分析、取结果</strong>，与人共管。关键判断是：电网研究不能靠&quot;聊天式生成&quot;，必须让 LLM 只做<strong>编排与解释</strong>，数值计算交给确定性求解器；难点在于<strong>工作流结构化、结果可核验、人类监督点</strong>如何在协议层落地。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2607.14158" target="_blank" rel="noreferrer">2607.14158</a></p><h3 id="🕸️-mycelium-把-科学发现-当网络问题-而不是单点推理问题" tabindex="-1">🕸️ Mycelium：把&quot;科学发现&quot;当网络问题，而不是单点推理问题 <a class="header-anchor" href="#🕸️-mycelium-把-科学发现-当网络问题-而不是单点推理问题" aria-label="Permalink to &quot;🕸️ Mycelium：把&quot;科学发现&quot;当网络问题，而不是单点推理问题&quot;">​</a></h3><p><strong>Networked Intelligence: Active Shared Context Graphs for Human-AI Team Science</strong><em>arXiv（2026）</em></p><p>当前 AI-for-Science 大多在<strong>放大单个推理过程</strong>：更强模型、更大上下文、更长程 agent、或服务单一 PI 的&quot;数字共同科学家&quot;。但难问题很少由单个推理者解决，而是由<strong>先验、实验背景、隐性知识与领域直觉各不相同的团队</strong>解决。Sutanay Choudhury、Jeffrey J. Czajka 等提出&quot;<strong>网络化智能（networked intelligence）</strong>&quot;并给出系统 <strong>Mycelium</strong>：一个自动连接研究者与 AI agent 的<strong>活跃共享工作区</strong>，实时捕获观察与假设、跟踪它们与团队演进中的知识模型的关系，并把信息<strong>路由给&quot;下一个决策能被它影响&quot;的人或 agent</strong>。评测是一个真实的多组学发现战役：一条本地分析发现经由共享上下文变成跨专家<strong>机制约束</strong>，最终转化为实验设计。作者进一步把网络化智能形式化为<strong>分布式科学上下文上的稀疏条件计算</strong>，并给出&quot;何时单机大 agent 够用、何时必须联网&quot;的判据。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2607.13220" target="_blank" rel="noreferrer">2607.13220</a></p><blockquote><p>📅 日期：2026-07-14 ｜ ⚠️ 事后重建版 ｜ 📂 科学前沿 5 篇 | 🤖 AI前沿 5 篇</p></blockquote>',45)])])}const m=o(a,[["render",s]]);export{p as __pageData,m as default};
